/* ─────────────────────────────────────────────────────────────────────────
 * gorand.js — bit-exact port of Go 1.x math/rand (v1) rngSource + Rand.
 *
 * Ports GOROOT/src/math/rand/{rng.go, rand.go, normal.go}. Deterministic given
 * a seed. uint64 arithmetic in the hot Int63/Uint64 path uses paired 32-bit
 * halves (no BigInt); seeding (cold) uses BigInt.
 *
 * Verified bit-exact against a Go dump of long sequences (see tests/parity/fill).
 * Float64 / NormFloat64 are compared as float64 bits.
 * ───────────────────────────────────────────────────────────────────────── */
"use strict";

const RNG_LEN = 607;
const RNG_TAP = 273;
const INT32MAX = 2147483647; // (1<<31) - 1
const TWO32 = 4294967296;
const TWO63 = 9223372036854775808; // 1<<63 as float64 (exact power of two)
const RN = 3.442619855899;
const MASK32 = 0xffffffff;

// seedrand: x[n+1] = 48271 * x[n] mod (2^31 - 1)  (Go int32 arithmetic)
function seedrand(x) {
  const A = 48271, Q = 44488, R = 3399;
  const hi = Math.trunc(x / Q);
  const lo = x % Q;
  x = A * lo - R * hi;
  if (x < 0) x += INT32MAX;
  return x;
}

class GoRand {
  constructor(seed) {
    this.vecHi = new Uint32Array(RNG_LEN);
    this.vecLo = new Uint32Array(RNG_LEN);
    this.tap = 0;
    this.feed = 0;
    // scratch outputs of _next()
    this._hi = 0; // raw uint64 high 32 bits
    this._lo = 0; // raw uint64 low 32 bits
    if (seed !== undefined && seed !== null) this.seed(seed);
  }

  // rngSource.Seed — cold path, BigInt for the int64 shifts/xor.
  seed(seedVal) {
    this.tap = 0;
    this.feed = RNG_LEN - RNG_TAP; // 334

    let s = Number(BigInt.asIntN(64, BigInt(seedVal)) % BigInt(INT32MAX));
    if (s < 0) s += INT32MAX;
    if (s === 0) s = 89482311;

    let x = s | 0; // int32
    const M64 = (1n << 64n) - 1n;
    for (let i = -20; i < RNG_LEN; i++) {
      x = seedrand(x);
      if (i >= 0) {
        let u = (BigInt(x) << 40n) & M64;
        x = seedrand(x);
        u = (u ^ (BigInt(x) << 20n)) & M64;
        x = seedrand(x);
        u = (u ^ BigInt(x)) & M64;
        u = (u ^ (BigInt.asUintN(64, RNG_COOKED[i]))) & M64;
        this.vecHi[i] = Number(u >> 32n) >>> 0;
        this.vecLo[i] = Number(u & 0xffffffffn) >>> 0;
      }
    }
  }

  // rngSource.Uint64 → sets this._hi/_lo to the raw uint64 (one advance).
  _next() {
    let tap = this.tap - 1;
    if (tap < 0) tap += RNG_LEN;
    let feed = this.feed - 1;
    if (feed < 0) feed += RNG_LEN;
    this.tap = tap;
    this.feed = feed;

    // x = vec[feed] + vec[tap]  (int64 add, wraps mod 2^64)
    const lo = this.vecLo[feed] + this.vecLo[tap];
    const carry = lo > MASK32 ? 1 : 0;
    const loW = lo >>> 0;
    const hiW = (this.vecHi[feed] + this.vecHi[tap] + carry) >>> 0;
    this.vecLo[feed] = loW;
    this.vecHi[feed] = hiW;
    this._hi = hiW;
    this._lo = loW;
  }

  // Int63 halves: hi has top bit cleared. Returns nothing; sets scratch.
  // Uint64() equivalent: (this._hi, this._lo).

  int63() {
    // Returns the full 63-bit value as a JS number (exact only if < 2^53;
    // callers that need bit-exactness use int63Hi/int63Lo directly).
    this._next();
    const hi = this._hi & 0x7fffffff;
    return hi * TWO32 + this._lo;
  }

  int31() {
    this._next();
    return this._hi & 0x7fffffff; // int32(Int63>>32)
  }

  uint32() {
    this._next();
    const hi = this._hi & 0x7fffffff; // int63 hi (31 bits)
    const lo = this._lo;             // int63 lo (32 bits)
    // uint32(Int63 >> 31) = ((hi<<1) | (lo>>>31)) mod 2^32
    return (hi * 2 + (lo >>> 31)) >>> 0;
  }

  float64() {
    for (;;) {
      this._next();
      const hi = this._hi & 0x7fffffff;
      const f = (hi * TWO32 + this._lo) / TWO63;
      if (f !== 1) return f;
    }
  }

  int31n(n) {
    // n is int32 > 0
    if ((n & (n - 1)) === 0) {
      return this.int31() & (n - 1);
    }
    const max = INT32MAX - ((2147483648 % n) | 0);
    let v = this.int31();
    while (v > max) v = this.int31();
    return v % n;
  }

  int63n(n) {
    // n is a JS integer > 0 (used only when n > 2^31-1; our shapes never hit
    // this, but ported for completeness using BigInt for the 63-bit modulus).
    const bn = BigInt(n);
    if ((bn & (bn - 1n)) === 0n) {
      const mask = bn - 1n;
      this._next();
      const v = ((BigInt(this._hi & 0x7fffffff) << 32n) | BigInt(this._lo >>> 0)) & mask;
      return Number(v);
    }
    const two63 = 1n << 63n;
    const max = two63 - 1n - (two63 % bn);
    for (;;) {
      this._next();
      const v = (BigInt(this._hi & 0x7fffffff) << 32n) | BigInt(this._lo >>> 0);
      if (v <= max) return Number(v % bn);
    }
  }

  intn(n) {
    if (n <= 0) throw new Error("invalid argument to Intn");
    if (n <= INT32MAX) return this.int31n(n | 0);
    return this.int63n(n);
  }

  normFloat64() {
    for (;;) {
      const j = this.uint32() | 0; // int32, possibly negative
      const i = j & 0x7f;
      const x = j * WN[i];
      const absj = j < 0 ? (-j >>> 0) : (j >>> 0);
      if (absj < KN[i]) return x;

      if (i === 0) {
        let xx, y;
        for (;;) {
          xx = -Math.log(this.float64()) * (1.0 / RN);
          y = -Math.log(this.float64());
          if (y + y >= xx * xx) break;
        }
        if (j > 0) return RN + xx;
        return -RN - xx;
      }
      // float32 arithmetic: fn[i] + float32(Float64())*(fn[i-1]-fn[i])
      const diff = Math.fround(FN[i - 1] - FN[i]);
      const prod = Math.fround(Math.fround(this.float64()) * diff);
      const lhs = Math.fround(FN[i] + prod);
      const rhs = Math.fround(Math.exp(-0.5 * x * x));
      if (lhs < rhs) return x;
    }
  }
}

